var t=`1248-jamaican-beef-patties`;var n=`world-1248`;var a=`JM`;var o=`central-america-caribbean`;var r=8;var s=83;var u={en:`Jamaican Beef Patties`,ua:`Ямайські пиріжки з яловичиною`};var g={en:`Jamaican Beef Patties is a dish from Jamaica featuring all-purpose flour, ground beef, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Ямайські пиріжки з яловичиною, страва кухні країни Ямайка з такими основними складниками: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,500,`g`],[`ground-turmeric`,5,`g`],[`unsalted-butter`,170,`g`],[`water`,200,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:17,i:[[`ground-beef`,550,`g`],[`yellow-onion`,160,`g`],[`garlic`,5,`clove`],[`scotch-bonnet-pepper`,1,`pcs`],[`thyme`,3,`sprig`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 32 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 32 хвилин до готовності.`,t:[`baking`],m:32,i:[]}];var d={slug:t,id:n,country:`JM`,region:o,servings:8,minutes:83,title:u,text:g,steps:l};export{a as country,d as default,n as id,s as minutes,o as region,r as servings,t as slug,l as steps,g as text,u as title};